"""Model-derived measurement questions, not manufacturing dimensions."""
def requests(d):
    a=d['assumptions'];c=d['candidate'];cx,cy=d['trim_center_mm'];ix,iy=d['inner_center_mm'];w=a['inner_width_mm'];h=a['inner_height_mm']
    byid={f['id']:f for f in d['features'] if 'contour_mm' in f}
    span_x=max(p[0] for p in byid['CUT-03']['contour_mm'])-min(p[0] for p in byid['CUT-01']['contour_mm'])
    span_y=max(p[1] for p in byid['CUT-01']['contour_mm'])-min(p[1] for p in byid['CUT-06']['contour_mm'])
    groups=[]
    def group(id,title,view,why,instructions,fields,first=True):
        groups.append(dict(id=id,title=title,view=view,purpose=why,instructions=instructions,fields=fields,first=first))
    def f(id,label,pred=None,accuracy=.5,method='caliper',contacts='',role='fitting input'):
        return dict(id=id,label=label,prediction_mm=pred,useful_accuracy_mm=accuracy,method=method,contacts=contacts,role=role)
    group('01','Check the wall scale','wall_measure', 'Calibrates the wall and valve scan; no CAD grid can establish physical scale.',
        'With the trim removed only if safely accessible, touch the two visible brass stem tips lightly. Measure along the line joining the tips: outside span O, then inside gap I. The center spacing is (O + I) / 2, even if tip diameters differ. Repeat both readings. If access risks turning hardware, have the installer take the readings. A straight-on photograph with a ruler beside both tips is the fallback, with lower accuracy.',
        [f('M01-O','O: farthest tip edges',None,.25,'caliper','A upper outside tangent to D lower outside tangent'),f('M01-I','I: gap between nearest tip edges',None,.25,'caliper','B upper inside tangent to C lower inside tangent')])
    group('02','Identify the inner plate datums','inner_measure','Replaces the assumed outline and prevents misleading hole coordinates.',
        'Place the loose factory inner plate on a padded surface. FRONT faces the handles (confirmed in the supplied photo); BACK faces the wall. Do not remove or compress the gasket. Use the leftmost tangent as datum A and bottommost tangent as datum B. Record the overall width and height; photograph front and back with those labels. The actual front photo shows a rounded rectangular outline; corner shape remains unmeasured. For a span beyond the caliper range, use two square blocks and a steel ruler.',
        [f('M02-W','Maximum metal outline width',w,.5,'caliper or blocks/ruler','A left tangent to opposite right tangent'),f('M02-H','Maximum metal outline height',h,.5,'blocks and steel ruler','B bottom tangent to top tangent')])
    slots=[]
    for label,slot in zip(['SW','NE'],d['inner_slots']):
        x,y=slot['center_mm'];slotw=slot['width_mm'];sloth=slot['height_mm']
        for suffix,label2,pred,contacts in [
            ('XN','near X edge',x-ix+w/2-slotw/2,'datum A to left edge of this opening'),('XF','far X edge',x-ix+w/2+slotw/2,'datum A to right edge of this opening'),
            ('YN','near Y edge',y-iy+h/2-sloth/2,'datum B to bottom edge of this opening'),('YF','far Y edge',y-iy+h/2+sloth/2,'datum B to top edge of this opening')]:
            slots.append(f('M03-'+label+'-'+suffix,label+' opening: '+label2,pred,.2,'caliper / tangent blocks',contacts))
    group('03','Locate the two mounting openings','inner_measure','Resolves hole/slot centers, size, and alignment with the actual diagonal studs.',
        'Use the same A and B tangent datums as Check 02. Measure to both the near and far edges of each opening, not an eyeballed center. X center from A = (XN + XF)/2; Y center from B = (YN + YF)/2. Opening width = XF - XN; height = YF - YN. Do not use a curved edge as a moving datum: square blocks against the outline can transfer A/B to a ruler. If these are round holes or different slots, record that and photograph them. Take the plate off only using the applicable factory procedure.',slots)
    group('04','Separate sheet thickness from formed depth','depth_measure','Controls the stack and rear interference; thin sheet can have a much larger formed envelope.',
        'Support the metal rear contact lands on equal blocks without loading the foam. Measure sheet thickness at an accessible unbent edge. Bridge the rear metal datum with a straightedge and measure to the frontmost formed metal face. Separately measure anything projecting toward the wall beyond that metal datum, and the forward hub projection. Mark the exact contact lands in the back photo. Do not flatten or bend the plate to measure it.',
        [f('M04-T','Metal sheet thickness',a['inner_sheet_thickness_mm'],.1,'caliper','opposite metal faces at same accessible edge'),f('M04-D','Rear metal datum to front formed face',a['inner_formed_depth_mm'],.2,'straightedge / depth gauge','rear metal lands to forward formed face'),f('M04-R','Largest rear metal projection',None,.2,'straightedge / depth gauge','rear land plane toward wall'),f('M04-H','Forward aperture rim / hub projection from rear datum',None,.2,'depth gauge','rear metal datum to frontmost aperture rim or attached hub end'),f('M04-O','Overall plate and free foam depth',None,.2,'caliper with light contact','uncompressed rear foam surface to frontmost metal')])
    group('05','Map the actual foam contact path','gasket_measure','Determines whether a plate aperture would remove gasket support.',
        'Photograph the BACK face straight on, with A/B labels and a ruler alongside it. Mark the inner and outer foam edges and every notch, joint, tear or missing segment. Measure overall contact-path width/height, band width at left/right/top/bottom, and free thickness without squeezing the foam. Record the smallest band width below and the other readings in notes. A single width does not confirm a continuous seal; the photo/trace remains necessary.',
        [f('M05-OW','Outer foam footprint width',a.get('gasket_outer_width_mm'),.5,'ruler or light caliper contact','left to right outer foam edges'),f('M05-OH','Outer foam footprint height',a.get('gasket_outer_height_mm'),.5,'ruler','bottom to top outer foam edges'),f('M05-W','Smallest observed contact band width',a['gasket_width_mm'],.5,'ruler','inner to outer foam edge at named location'),f('M05-T','Uncompressed foam thickness',a['gasket_free_thickness_mm'],.5,'ruler / noncompressing depth comparison','rear foam surface to metal backing'),f('M05-B','Representative foam band width',None,.5,'light caliper contact / ruler','inner to outer foam edge; location and minimum not established')])
    group('06','Place the real outer trim','trim_measure','Separates trim center from valve axes and mounting midpoint; replaces nominal diameter.',
        'Protect the brushed finish. Measure the circular outer rim diameter in two directions and report any difference. Using left and bottom rim tangent blocks as datums, measure near/far edges of the LOWER control opening. Its center follows from the paired edges, so no center mark is needed. Measure the rear rim-contact plane to the inner cavity surface beside EACH stud location; report the smaller clearance and both locations in notes. Keep the drain notch at 6 oclock. Do not use the decorative front face as the rear contact datum.',
        [f('M06-OD','Outer rim diameter',d['nominal']['trim_diameter_mm'],.5,'blocks/ruler or large caliper','opposite rim tangents'),f('M06-XN','Left rim tangent to lower opening near edge',d['nominal']['trim_diameter_mm']/2-cx-18,.3,'caliper / blocks','left tangent to left edge of lower bore'),f('M06-XF','Left rim tangent to lower opening far edge',d['nominal']['trim_diameter_mm']/2-cx+18,.3,'caliper / blocks','left tangent to right edge of lower bore'),f('M06-YN','Bottom rim tangent to lower opening near edge',d['nominal']['trim_diameter_mm']/2-cy-18,.3,'caliper / blocks','bottom tangent to bottom edge of lower bore'),f('M06-YF','Bottom rim tangent to lower opening far edge',d['nominal']['trim_diameter_mm']/2-cy+18,.3,'caliper / blocks','bottom tangent to top edge of lower bore'),f('M06-C','Minimum rear cavity depth at stud locations',None,.25,'straightedge / depth gauge','rear rim plane to inside shell next to each stud')])
    group('07','Measure both stud projections','stud_measure','Tests apparent seating interference without shortening studs or moving the valve.',
        'Have the installer establish a straightedge plane on two equal-height blocks resting on intact tile. Choose blocks taller than both studs. Measure block height H, then gap G from the straightedge underside to each stud tip. Tip projection is H - G. Record any local tile lippage and do not rest the reference on a cut or grout recess. The installer also records adjustment range, engaged threads, nuts and adapters; visible tips cannot establish these. Do not cut studs or force the outer trim.',
        [f('M07-H','Reference-block height H',None,.25,'caliper','tile-contact face to straightedge-contact face'),f('M07-GSW','Gap G to lower-left stud tip',None,.25,'depth gauge','straightedge underside to SW tip'),f('M07-GNE','Gap G to upper-right stud tip',None,.25,'depth gauge','straightedge underside to NE tip')])
    group('08','Check the worst cuts and current state','wall_measure','Independently checks scale/coverage and identifies changes since capture.',
        'Measure the horizontal span P-Q from the leftmost upper cut end to the rightmost upper cut end, and the vertical span U-V from the highest upper damage to the lowest bottom chipped edge, using the labeled scan view. Do not add these as calibration inputs until their independent-check role is reviewed. Identify whether CUT-02/CUT-07 are real cuts or texture/shadow, and whether MARK-01 is only residue. At GROUT-01 record recess width/depth. No changes since capture were confirmed on 2026-10-14. Report only subsequent changes to piping, valve pose, studs or wall, with photographs of altered areas.',
        [f('M08-X','P-Q upper damage span',span_x,.75,'steel ruler / straightedge','leftmost CUT-01 end to farthest CUT-03 end','independent cross-check'),f('M08-Y','U-V damage height',span_y,1,'steel ruler / straightedge','highest CUT-01 to lowest CUT-06','independent cross-check'),f('M08-GW','Adjacent grout recess width',None,.5,'ruler','stone edge to stone edge at marked seam'),f('M08-GD','Adjacent grout recess depth',None,.25,'straightedge / depth gauge','intact stone plane to grout surface')])
    group('09','Installer checks before selecting a repair','section_studs','Resolves inaccessible and hidden conditions without asking the homeowner to probe plumbing.',
        'The user reports rear bolt contact with wood. Trace those fasteners to confirm whether they are the diagonal trim studs. Record whether the wood is structural framing or added blocking, rear clearance, usable threads, nut bearing seats, washers and stops. Trim studs thread into the valve; wood is not their required anchor. Separately identify the plaster guard, installed adapters and available alternatives; verify valve depth from the documented datum. Inspect foam compression, support and visible waterproofing through existing access. Keep cartridge/tool access and the lower diverter clear. The 7/16-inch limit applies to trim studs, not control stems. No stud cutting, wood drilling, valve move or unseen waterproofing detail is selected.',[],False)
    group('10','Identify and measure the control tips','control_depth_measure','Separates bare-stem projection, adapter length and valve rough-in depth; the upper scan tip currently triggers a conditional depth flag.',
        'Identify the actual exposed upper tip U and lower tip L in a photo; record any attached spline/stem adapter, number or unknown identity. Do not remove a pressure-containing part to identify it. Use equal measured blocks on intact tile and a straightedge above both tips, as in Check 07. Record block height H and the gap from the straightedge UNDERSIDE to each as-found tip. Projection = H - G; a negative result means recessed behind tile. Read H again for this setup. These readings remain diagnostic until tip identity is resolved. The installer checks the plaster guard or manufacturer rough-in datum separately. Do not apply the 7/16-inch stud limit to these tips.',
        [f('M10-H','Control setup block height H',None,.25,'caliper','tile-contact face to straightedge underside','diagnostic cross-check; tip identity required'),f('M10-GU','Gap G to upper as-found tip U',None,.25,'depth gauge','straightedge underside to identified upper tip U','diagnostic cross-check; tip identity required'),f('M10-GL','Gap G to lower as-found tip L',None,.25,'depth gauge','straightedge underside to identified lower tip L','diagnostic cross-check; tip identity required')],False)
    group('11','Complete the photographed inner plate','inner_photo','Uses the actual front face and separates edge gaps from center distances.',
        'Front faces the handles. SW is the lower-left mounting hole; NE is the upper-right mounting hole. The supplied photo records width 130.35 mm, height 6.5 inches, upper opening 48.46 mm, top gap 18 mm, SW hole 5.66 mm, nearest-edge diagonal gap 106.39 mm and NE hole-to-right-rim gap 11.71 mm. Do not enter these again unless correcting them. Measure the NE hole and lower control opening independently. Diagonal center spacing requires BOTH mounting-hole diameters: gap + half of each diameter. Mounting-hole Y positions still need Check 03. The front photo does not establish the rear foam path or any Z depth.',
        [f('M11-UD','Upper control opening diameter',None,.2,'caliper inside jaws','left inside edge to right inside edge of upper large opening'),
         f('M11-UT','Top rim to upper opening top edge',None,.3,'caliper','topmost outer metal tangent to top inside edge of upper large opening'),
         f('M11-LD','Lower control opening diameter',None,.2,'caliper inside jaws','left inside edge to right inside edge of lower large opening'),
         f('M11-SWD','SW mounting-hole diameter',None,.1,'caliper inside jaws','opposite inside edges of lower-left round mounting hole, front view'),
         f('M11-NED','NE mounting-hole diameter',None,.1,'caliper inside jaws','opposite inside edges of upper-right round mounting hole, front view'),
         f('M11-G','Nearest-edge diagonal gap',None,.2,'caliper','nearest edges of SW and NE mounting holes along their center line'),
         f('M11-R','NE hole edge to right outer rim',None,.2,'caliper','right inside edge of NE hole to rightmost outer metal tangent')],False)
    group('12','Complete the photographed outer cover','outer_photo','Separates measured opening diameters and edge gaps from cover placement and rear clearance.',
        'The supplied photo shows the FRONT toward the handles. Outer diameter 7.25 inches (184.15 mm) was measured by tape; the upper opening is 33.79 mm by caliper. The blue annotation reports a 46.25 mm gap and the orange annotation 35.23 mm to the bottom rim; their exact inside-edge versus raised-lip contacts await clarification. Do not repeat these readings unless correcting them. Measure the LOWER opening inside diameter independently. Both diameters and a confirmed inside-edge gap are needed for vertical center spacing. The photo does not establish rear cavity depth: use Check 06-C beside both studs.',
        [f('M12-UD','Outer cover: upper opening inside diameter',None,.2,'caliper inside jaws','left inside edge to right inside edge of upper cover opening'),
         f('M12-LD','Outer cover: lower opening inside diameter',None,.2,'caliper inside jaws','left inside edge to right inside edge of lower cover opening'),
         f('M12-G','Outer cover: vertical gap between inside opening edges',None,.2,'caliper','bottom inside edge of upper opening to top inside edge of lower opening; vertical projection')],False)
    return groups
